{
  "passageId": "diffusion-model-ai",
  "items": [
    {
      "id": "R1",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "확산 이미지 형성 설명에 쓰인 ‘노이즈’라는 용어의 뜻을 불필요하거나 원하지 않는 값으로 풀이한다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노이즈 추가가 누적되어 원본을 알아볼 수 없는 노이즈 이미지가 되는 실제 변화를 설명한다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "노이즈를 더해 원본을 알아볼 수 없게 되는 방향과 그 노이즈를 알아 원본을 복원하는 역방향을 대비한다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "전체 작동 순서에서 언급한 순확산 과정을 노이즈 추가 절차와 예측기 학습 내용으로 자세히 풀어 설명한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "전체 작동 순서에서 언급한 역확산 과정을 노이즈 예측과 제거의 반복 절차로 구체화한다."
    },
    {
      "id": "R6",
      "type": "PROCESS",
      "otherName": "",
      "reason": "노이즈 생성기가 노이즈를 만든 다음 이미지 연산기가 이를 더하는 작업 순서를 제시한다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "원본 이미지에 노이즈를 더하는 연산이 노이즈를 포함한 확산 이미지의 출력을 만들어 낸다."
    },
    {
      "id": "R8",
      "type": "PROCESS",
      "otherName": "",
      "reason": "원본 이미지에 노이즈를 더하는 첫 단계에서 이전 출력에 노이즈를 더하는 다음 단계로 이어지는 순서를 설명한다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "확산 이미지에 노이즈를 추가하는 작업의 반복이 최종 노이즈 이미지를 만들어 낸다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "단계마다 노이즈 특성이 다르다는 사실이 단계별 이미지에서 특성을 추출하여 예측하는 방식을 설명하는 근거이다."
    },
    {
      "id": "R11",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "노이즈 특성을 수치로 표현하는 작업이 그 수치를 이용해 노이즈를 예측하기 위한 수단이 된다."
    },
    {
      "id": "R12",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "노이즈 특성을 표현한 예측기 내부의 수치들을 ‘잠재 표현’이라고 명명한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "예측기가 학습한다는 설명을 정답과 예측의 차이를 줄이는 지도 학습의 구체적인 방식으로 풀어 준다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "정답과 출력의 차이를 줄인다는 지도 학습의 일반 원리를 노이즈 예측기의 학습에 적용한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "생성기가 넣은 노이즈가 정답이라는 사실에 따라 그것과 예측된 노이즈의 차이를 줄이는 학습 방식이 도출된다."
    },
    {
      "id": "R16",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "복원하려면 더해진 노이즈를 알아야 한다는 설명을 그 정보를 알아내는 노이즈 예측기의 역할로 구체화한다."
    },
    {
      "id": "R17",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "지도 학습으로 익힌 노이즈 예측 방식을 역확산 단계의 이미지에 적용하여 실제 노이즈를 예측한다."
    },
    {
      "id": "R18",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "이미지에서 노이즈 특성을 수치화하고 이를 바탕으로 예측한다는 동일한 작동 내용을 ‘잠재 표현’이라는 용어로 다시 서술한다."
    },
    {
      "id": "R19",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "이미지의 노이즈 특성을 추출해 잠재 표현을 구하는 작업이 노이즈를 예측하는 수단으로 쓰인다."
    },
    {
      "id": "R20",
      "type": "PROCESS",
      "otherName": "",
      "reason": "노이즈 예측기가 노이즈를 예측한 다음 이미지 연산기가 그 노이즈를 빼는 작업 순서를 제시한다."
    },
    {
      "id": "R21",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노이즈를 예측하고 제거하는 작업의 반복이 노이즈를 대부분 없애 원본에 가까운 이미지를 남긴다."
    },
    {
      "id": "R22",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "순확산과 역확산을 노이즈의 추가와 제거, 예측기의 학습과 이미지 복원이라는 기준에서 대비한다."
    },
    {
      "id": "R23",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "원본 복원에 사용하는 역확산 방식을 잠재 표현의 고유 번호를 활용한 이미지 선택 생성에 가져다 쓴다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "노이즈 특성을 나타내는 잠재 표현을 이미지 선택 생성과 혼합 및 새로운 이미지 생성에 활용한다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "잠재 표현 조정으로 노이즈 특성이 달라지는 것이 여러 이미지의 혼합을 가능하게 하는 실제 작용으로 이어진다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "잠재 표현 조정으로 노이즈 특성이 달라지는 것이 실재하지 않는 이미지의 생성을 가능하게 한다."
    }
  ]
}

